var VIET = /[àáảãạăằắẳẵặâầấẩẫậèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữựỳýỷỹỵđ]/i;
var LET = /[A-Za-z0-9À-ỹ]/;
var RULES = { zh:[[/Tuần\s*(\d+)/g, "第 $1 週"], [/tháng\s*(\d+)/g, "$1 月"], [/Chương\s*(\d+)/g, "第 $1 章"]],
              en:[[/Tuần\s*(\d+)/g, "Week $1"], [/tháng\s*(\d+)/g, "month $1"], [/Chương\s*(\d+)/g, "Chapter $1"]] };
function mk(dict, rules){
  var keys = Object.keys(dict).sort(function(a, b){ return b.length - a.length; }), byFirst = {};
  keys.forEach(function(k){ var c = k.charAt(0); (byFirst[c] || (byFirst[c] = [])).push(k); });
  return { dict:dict, rules:rules, byFirst:byFirst, cache:Object.create(null) };
}
var LZ = mk(D, RULES.zh), LE = mk(E, RULES.en);
function isLet(ch){ return !!ch && LET.test(ch); }
function hasVN(s){ return typeof s === "string" && (VIET.test(s) || /\b(Nghe|Xem|CN|T[2-7]|sao)\b/.test(s)); }
function conv(L, s){
  if (typeof s !== "string" || !hasVN(s)) return s;
  if (s in L.cache) return L.cache[s];
  var t = s.trim(), out = null;
  if (L.dict[t] != null) out = s.replace(t, L.dict[t]); else out = tokens(L, s);
  return L.cache[s] = (out == null ? s : out);
}
function tokens(L, s0){
  var s = s0.replace(/ {2,}/g, " "); L.rules.forEach(function(r){ s = s.replace(r[0], r[1]); });
  var i = 0, out = "", hit = s !== s0, last = "";
  while (i < s.length){
    var ch = s.charAt(i);
    if (!isLet(ch)){ out += ch; i++; continue; }
    var found = null, A = L.byFirst[ch];
    if (A) for (var j = 0; j < A.length; j++){ var k = A[j];
      if (s.startsWith(k, i) && (!isLet(s.charAt(i - 1)) || !isLet(k.charAt(0))) && (!isLet(s.charAt(i + k.length)) || !isLet(k.charAt(k.length - 1)))){ found = k; break; } }
    if (found){ out += L.dict[found]; i += found.length; hit = true; last = found; continue; }
    var j2 = i; while (j2 < s.length && isLet(s.charAt(j2))) j2++;
    var w = s.slice(i, j2); if (VIET.test(w)){ if (hit && /[:：]$/.test(last)) return out + s.slice(i); return null; }
    out += w; i = j2;
  }
  return hit ? out : null;
}
var SKIP = function(){ return location.hash.indexOf("#/admin") === 0; };
var PAIR = " || ";
/* tr: chữ hiển thị (tiếng Anh); zh: bản tiếng Trung cho bong bóng ("" nếu không có) */
function tr(s){ if (SKIP() || typeof s !== "string") return s; var p = s.indexOf(PAIR); if (p > 0) return s.slice(0, p); return conv(LE, s); }
function zh(s){ if (SKIP() || typeof s !== "string") return ""; var p = s.indexOf(PAIR); if (p > 0) return s.slice(p + PAIR.length).trim(); if (!hasVN(s)) return ""; var z = conv(LZ, s); return z === s ? "" : z; }
var ATTRS = ["placeholder", "title", "aria-label", "alt"];
var NZ = typeof WeakMap === "function" ? new WeakMap() : null;
function setZh(p, node, z){
  if (!p || p.nodeType !== 1 || !NZ) return;
  var m = NZ.get(p); if (!m){ m = new Map(); NZ.set(p, m); } if (z) m.set(node, z); else m.delete(node);
  var parts = [], c; for (c = p.firstChild; c; c = c.nextSibling){ if (m.has(c)) parts.push(m.get(c)); }
  if (parts.length) p.setAttribute("data-zh", parts.join(" ")); else p.removeAttribute("data-zh");
}
function fixNode(n, fresh){
  if (n.nodeType === 3){ var p = n.parentNode; if (p && /^(SCRIPT|STYLE|TEXTAREA)$/.test(p.nodeName)) return;
    var d = n.data, t = tr(d), z = t !== d || d.indexOf(PAIR) > 0 ? zh(d) : "";
    if (t !== d) n.data = t;
    if (z) setZh(p, n, z); else if (fresh && p && p.nodeType === 1 && p.hasAttribute("data-zh") && !(NZ && NZ.get(p) && NZ.get(p).has(n))) setZh(p, n, "");
    return; }
  if (n.nodeType !== 1) return;
  if (/^(SCRIPT|STYLE)$/.test(n.nodeName)) return;
  ATTRS.forEach(function(a){ if (n.hasAttribute && n.hasAttribute(a)){ var v = n.getAttribute(a), t = tr(v); if (t !== v) n.setAttribute(a, t); } });
  for (var c = n.firstChild; c; c = c.nextSibling) fixNode(c, fresh);
}
/* bong bóng tiếng Trung khi rê chuột (hoặc giữ ngón tay trên màn hình cảm ứng) */
var tip = null, tipFor = null, tipTimer = null, pressTimer = null;
function ensureTip(){
  if (tip) return tip; tip = document.createElement("div"); tip.className = "zhtip"; tip.setAttribute("role", "tooltip"); tip.hidden = true; document.body.appendChild(tip); return tip;
}
function findZh(el){ for (var i = 0; el && el.nodeType === 1 && i < 8; i++, el = el.parentNode){ if (el.hasAttribute("data-zh")) return el; } return null; }
function showTip(el){
  var t = ensureTip(); tipFor = el; t.textContent = el.getAttribute("data-zh"); t.hidden = false;
  var r = el.getBoundingClientRect(), tw = t.offsetWidth, th = t.offsetHeight, vw = document.documentElement.clientWidth, vh = window.innerHeight;
  var x = Math.max(8, Math.min(r.left + r.width / 2 - tw / 2, vw - tw - 8)), y = r.bottom + 8; if (y + th > vh - 8) y = Math.max(8, r.top - th - 8);
  t.style.left = x + "px"; t.style.top = y + "px";
}
function hideTip(){ clearTimeout(tipTimer); tipFor = null; if (tip) tip.hidden = true; }
function bindTip(){
  document.addEventListener("mouseover", function(e){
    var el = findZh(e.target); if (el === tipFor) return; clearTimeout(tipTimer);
    if (!el){ hideTip(); return; } tipTimer = setTimeout(function(){ showTip(el); }, 120);
  });
  document.addEventListener("mouseleave", hideTip, true);
  document.addEventListener("scroll", hideTip, true); document.addEventListener("keydown", hideTip, true);
  document.addEventListener("touchstart", function(e){ var el = findZh(e.target); clearTimeout(pressTimer); if (!el) { hideTip(); return; }
    pressTimer = setTimeout(function(){ showTip(el); setTimeout(hideTip, 4000); }, 450); }, { passive:true });
  ["touchend", "touchmove", "touchcancel"].forEach(function(ev){ document.addEventListener(ev, function(){ clearTimeout(pressTimer); }, { passive:true }); });
}
function start(){
  document.documentElement.lang = "en";
  fixNode(document.documentElement); document.title = tr(document.title);
  bindTip();
  new MutationObserver(function(ms){
    ms.forEach(function(m){
      if (m.type === "characterData") fixNode(m.target);
      else if (m.type === "attributes") fixNode(m.target);
      else m.addedNodes.forEach(function(a){ fixNode(a, true); });
    });
  }).observe(document.documentElement, { childList:true, subtree:true, characterData:true, attributes:true, attributeFilter:ATTRS });
}
var oc = window.confirm, oa = window.alert, op = window.prompt;
window.confirm = function(m){ return oc.call(window, tr(String(m))); };
window.alert = function(m){ return oa.call(window, tr(String(m))); };
window.prompt = function(m, d){ return op.call(window, tr(String(m)), d); };
